<script setup lang="ts">
import { Check, ImagePlus, Link, LoaderCircle, Search, Trash2, Upload, X } from 'lucide-vue-next'
const props=defineProps<{modelValue?:string|null;label?:string}>()
const {user}=useAuth()
const emit=defineEmits(['update:modelValue','selected'])
const dialog=ref<HTMLDialogElement>(),items=ref<any[]>([]),page=ref(1),busy=ref(false),error=ref(''),alt=ref(''),query=ref(''),lastCount=ref(0)
const selected=ref(''),failed=ref(false)
watch(()=>props.modelValue,()=>{failed.value=false})
async function load(){busy.value=true;error.value='';try{const result=await $fetch<any>('/api/admin/media',{query:{page:page.value,q:query.value}});items.value=result.items;lastCount.value=result.items.length}catch{error.value='Նկարները չհաջողվեց բեռնել։ Փորձիր կրկին։'}finally{busy.value=false}}
function open(){selected.value=props.modelValue||'';page.value=1;dialog.value?.showModal();void load()}
function choose(){emit('update:modelValue',selected.value);emit('selected',items.value.find(x=>x.url===selected.value)||null);dialog.value?.close()}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>800000){error.value='Ընտրիր մինչև 800 ԿԲ նկար։';return}const form=new FormData();form.append('file',file);form.append('alt',alt.value);busy.value=true;error.value='';try{const item=await $fetch<any>('/api/admin/upload',{method:'POST',body:form});selected.value=item.url;await load()}catch(e:any){error.value=e.statusCode===503||e.data?.statusCode===503?'Ֆայլերի վերբեռնումը դեռ միացված չէ։ Կարող ես օգտագործել նկարի հղումը՝ ստորև։':e.data?.statusMessage||'Նկարը չվերբեռնվեց։ Փորձիր կրկին։'}finally{busy.value=false;(event.target as HTMLInputElement).value=''}}
async function remove(item:any){
 if(!confirm('Հեռացնե՞լ նկարը պահոցի ցանկից։ Նյութերում օգտագործվող նկարի հղումը կշարունակի աշխատել։'))return
 busy.value=true;error.value=''
 try{await $fetch('/api/admin/media',{method:'DELETE',query:{id:item.id}});if(selected.value===item.url)selected.value='';await load()}
 catch{error.value='Նկարը չհաջողվեց հեռացնել։ Փորձիր կրկին։'}finally{busy.value=false}
}
</script>
<template><div class="image-field"><div v-if="modelValue" class="image-preview"><img v-if="!failed" :src="modelValue" :alt="label||'Ընտրված նկար'" loading="lazy" @error="failed=true"><p v-else>Նկարը չի բացվում․ ստուգիր հղումը։</p><button type="button" aria-label="Հեռացնել ընտրված նկարը" @click="emit('update:modelValue','')"><X :size="16"/></button></div><button type="button" class="choose-image" @click="open"><ImagePlus :size="18"/>{{modelValue?'Փոխել նկարը':'Ընտրել կամ ավելացնել նկար'}}</button><details class="image-url"><summary><Link :size="13"/>Օգտագործել նկարի հղում</summary><input :value="modelValue||''" type="text" aria-label="Նկարի հղում" placeholder="https://… կամ /images/…" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)"></details><dialog ref="dialog" class="image-dialog" @click="($event.target===dialog)&&dialog?.close()"><div class="dialog-inner"><header><div><p>FACTUM · ՆԿԱՐՆԵՐ</p><h2>Ընտրիր նկարը</h2></div><button type="button" aria-label="Փակել նկարների ընտրությունը" @click="dialog?.close()"><X :size="22"/></button></header><div class="image-search"><Search :size="17"/><input v-model="query" type="search" aria-label="Որոնել նկարները" placeholder="Որոնիր նկարագրությամբ…" @keydown.enter.prevent="page=1;load()"><button type="button" @click="page=1;load()">Որոնել</button></div><div class="upload-row"><input v-model="alt" aria-label="Վերբեռնվող նկարի նկարագրություն" placeholder="Նկարի նկարագրություն (ոչ պարտադիր)"><label class="upload-button"><Upload :size="16"/>Վերբեռնել<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" :disabled="busy" @change="upload"></label></div><p class="upload-note">JPG, PNG, WebP կամ AVIF · մինչև 800 ԿԲ</p><p v-if="error" class="image-error" role="alert">{{error}}</p><p v-if="busy" class="loading"><LoaderCircle :size="18"/>Բեռնվում է…</p><div v-else class="picker-grid"><div v-for="item in items" :key="item.id" class="picker-item"><button type="button" :class="{selected:selected===item.url}" :aria-pressed="selected===item.url" @click="selected=item.url"><img :src="item.url" :alt="item.alt" loading="lazy"><span>{{item.alt||'Նկար'}}</span><Check v-if="selected===item.url" class="selected-check" :size="20"/></button><button v-if="user?.role==='ADMIN'" type="button" class="delete-image" :aria-label="`Հեռացնել պահոցից՝ ${item.alt||'նկար'}`" @click="remove(item)"><Trash2 :size="14"/>Հեռացնել պահոցից</button></div><p v-if="!items.length" class="empty-images">Այստեղ դեռ նկար չկա։ Ավելացրու նոր նկար կամ օգտագործիր նկարի հղումը։</p></div><div class="picker-pagination"><button type="button" :disabled="page===1||busy" @click="page--;load()">← Նախորդ</button><span>{{page}}</span><button type="button" :disabled="lastCount<25||busy" @click="page++;load()">Հաջորդ →</button></div><div class="direct-image"><label>Կամ տեղադրիր նկարի հղումը<input v-model="selected" placeholder="https://… կամ /images/…"></label></div><footer><button type="button" class="cancel" @click="dialog?.close()">Չեղարկել</button><button type="button" class="apply" :disabled="!selected" @click="choose"><Check :size="17"/>Օգտագործել այս նկարը</button></footer></div></dialog></div></template>
<style scoped>.image-field{display:grid;gap:10px}.image-preview{position:relative;max-width:320px;border:1px solid #304661;border-radius:12px;overflow:hidden;background:#071426}.image-preview img{width:100%;height:170px;object-fit:contain}.image-preview>button{position:absolute;right:8px;top:8px;padding:6px;background:#071426e8;border-radius:50%;color:#fff}.image-preview p{padding:24px;font-size:12px;color:#f3b1ac}.choose-image{display:flex;align-items:center;justify-content:center;gap:10px;border:1px dashed #526989;border-radius:11px;background:#13243a80;color:#ebc78a;padding:16px;font-size:12px}.choose-image:hover{border-color:#e5c183}.image-url{font-size:11px;color:#8fa4c0}.image-url summary{display:flex;align-items:center;gap:6px;cursor:pointer}.image-url input{margin-top:10px}input{width:100%;min-width:0;background:#071426;border:1px solid #304661;border-radius:9px;padding:12px;color:#e8effa;font:inherit;font-size:12px}.image-dialog{padding:0;color:#e8effa;border:1px solid #3b506a;border-radius:20px;background:#0b192c;width:min(760px,calc(100vw - 28px));max-height:85vh}.image-dialog::backdrop{background:#020814bb;backdrop-filter:blur(5px)}.dialog-inner{padding:26px}.dialog-inner header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.dialog-inner header p{font-size:9px;letter-spacing:2px;color:#e7c789;margin-bottom:7px}.dialog-inner h2{font-size:23px;font-weight:750}.image-search{display:flex;align-items:center;gap:10px;margin-bottom:18px}.image-search>svg{color:#8fa4c0;flex-shrink:0}.image-search button,.picker-pagination button{font-size:12px;color:#e7c789;white-space:nowrap}.upload-row{display:grid;grid-template-columns:1fr auto;gap:12px}.upload-button{display:flex;align-items:center;justify-content:center;gap:8px;background:#1b3048;border:1px solid #415974;border-radius:9px;font-size:12px;padding:10px;cursor:pointer}.upload-button input{display:none}.upload-note{font-size:10px;color:#8fa4c0;margin:8px 0 18px}.picker-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.picker-item>button:not(.delete-image){position:relative;text-align:left;border:1px solid #2c425c;border-radius:12px;overflow:hidden;background:#071426}.picker-item>button:not(.delete-image).selected{border-color:#efce8d;box-shadow:0 0 0 2px #efce8d33}.picker-grid img{width:100%;height:115px;object-fit:cover}.picker-grid button span{display:block;padding:10px;font-size:10px;overflow-wrap:anywhere}.selected-check{position:absolute;right:8px;top:8px;background:#efce8d;color:#071426;border-radius:50%;padding:2px}.empty-images{grid-column:1/-1;text-align:center;padding:30px;color:#9badc4;font-size:12px;line-height:2}.picker-pagination{display:flex;justify-content:space-between;margin:20px 0;font-size:12px}.direct-image{border-top:1px solid #2c425c;padding-top:18px}.direct-image label{display:grid;gap:8px;font-size:12px}.dialog-inner footer{display:flex;justify-content:flex-end;gap:16px;margin-top:24px}.cancel{font-size:12px;color:#a6b6cd}.apply{display:flex;align-items:center;gap:8px;padding:12px;background:linear-gradient(110deg,#f4d9a2,#e6b65f);color:#102037;border-radius:9px;font-size:12px;font-weight:750}.image-error{font-size:12px;color:#f4b0a9;padding:12px;background:#f8717110;margin-bottom:15px;border-radius:9px;line-height:1.9}.loading{display:flex;gap:8px;justify-content:center;padding:25px}button:disabled{opacity:.4}@media(max-width:520px){.dialog-inner{padding:18px}.picker-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.upload-row{grid-template-columns:1fr}.dialog-inner footer{flex-wrap:wrap}}.picker-item{min-width:0}.picker-item>button:not(.delete-image){width:100%}.delete-image{display:flex;align-items:center;gap:6px;color:#f4b0a9;padding:9px 2px;font-size:10px}</style>
